function normalizeCompetition(state){
 const eventName=String(state.eventName||'').trim().toUpperCase();
 if(eventName.startsWith('CS2 ')&&eventName.includes('COMMUNITY'))state.eventName='CAVERNA GAMER CUP';
 if(!state.competition||typeof state.competition!=='object')state.competition={matches:[]};
 if(!Array.isArray(state.competition.matches))state.competition.matches=[];
 state.players.forEach(p=>{if(!p.externalStats||typeof p.externalStats!=='object')p.externalStats={};});
 state.draft.teams.forEach((t,i)=>{if(!t.group)t.group='A';if(!t.id)t.id=`team${i+1}`;});
 return state;
}
