let cloud=null, cloudUser=null, cloudRole=null, cloudBusy=false;
const ADMIN_IDLE_MS=30*60*1000,ADMIN_ACTIVITY_KEY='vanta_admin_last_activity';
let adminIdleTimer=null,adminActivityBound=false,adminLastActivity=0,adminLastStored=0,adminEnding=false;
const canEdit=()=>!cloudConfigured||!!(cloudLoadStatus==='ready'&&cloudUser&&['owner','editor'].includes(cloudRole)&&adminSessionIsFresh());
function getAdminActivity(){try{return Number(sessionStorage.getItem(ADMIN_ACTIVITY_KEY))||0;}catch{return adminLastActivity;}}
function touchAdminSession(force=false){if(!cloudConfigured||!cloudUser)return;const now=Date.now();adminLastActivity=now;if(force||now-adminLastStored>1000){try{sessionStorage.setItem(ADMIN_ACTIVITY_KEY,String(now));}catch{}adminLastStored=now;}}
function adminSessionIsFresh(){if(!cloudConfigured||!cloudUser)return false;const last=getAdminActivity();if(!last){touchAdminSession(true);return true;}if(Date.now()-last>=ADMIN_IDLE_MS){expireAdminSession('inactivity');return false;}return true;}
async function expireAdminSession(reason='logout'){if(adminEnding||!cloud)return;adminEnding=true;if(adminIdleTimer){clearInterval(adminIdleTimer);adminIdleTimer=null;}try{sessionStorage.removeItem(ADMIN_ACTIVITY_KEY);}catch{}adminLastActivity=0;adminLastStored=0;cloudUser=null;cloudRole=null;ui.modal=null;$('#modalRoot').innerHTML='';render();try{const {error}=await cloud.auth.signOut({scope:'local'});if(error)console.error('Supabase signOut:',error.message);}catch(e){console.error('Supabase signOut:',e);}if(reason==='inactivity')toast('Sessão administrativa encerrada após 30 minutos sem atividade.',true);adminEnding=false;}
function bindAdminSessionMonitor(){if(adminActivityBound)return;adminActivityBound=true;const activity=()=>{if(!cloudUser)return;if(!adminSessionIsFresh())return;touchAdminSession();};['pointerdown','keydown','touchstart','mousemove','scroll'].forEach(type=>window.addEventListener(type,activity,{passive:true}));window.addEventListener('focus',activity);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')activity();});if(adminIdleTimer)clearInterval(adminIdleTimer);adminIdleTimer=setInterval(()=>{if(cloudUser&&!adminSessionIsFresh())return;},5000);}
