async function loadCloud(){if(!cloud)return;try{const [{data:state,error:stateError},{data:newsRows,error:newsError}]=await Promise.all([cloud.from('site_state').select('data').eq('id',1).maybeSingle(),cloud.from('news_posts').select('*').order('published_at',{ascending:false})]);if(stateError)throw stateError;if(state&&!state.data)throw Error('Dados do campeonato inválidos.');const remote=state?.data||createEmptyState();if(!Array.isArray(remote.players)||!remote.draft||!Array.isArray(remote.draft.teams)||!Array.isArray(remote.draft.log))throw Error('Dados do campeonato inválidos.');db=normalizeCompetition(remote);db.eventName=String(db.eventName||'CAVERNA GAMER CUP').slice(0,44);ui.editingId=db.players[0]?.id||'new';if(newsError)toast('Não foi possível carregar notícias: '+newsError.message,true);else articles=(newsRows||[]).map(n=>({id:n.id,title:n.title,summary:n.summary,body:n.body,category:n.category,imageUrl:n.image_url||'',author:n.author,status:n.status,publishedAt:n.published_at}));cloudLoadStatus='ready';const stat=$('#syncStatus');if(stat)stat.textContent=canEdit()?'Editor conectado':'Leitura pública · nuvem';render();}catch(e){cloudLoadStatus='error';const stat=$('#syncStatus');if(stat)stat.textContent='Falha na conexão com a nuvem';render();}}
