async function initCloud(){if(!cloudConfigured)return;cloudLoadStatus='loading';const stat=$('#syncStatus');if(stat)stat.textContent='Conectando aos dados...';render();try{if(!window.supabase?.createClient)throw Error('Biblioteca Supabase não carregou; confira a conexão.');if(!cloud){cloud=window.supabase.createClient(CLOUD_CONFIG.supabaseUrl,CLOUD_CONFIG.supabasePublishableKey,{auth:{storage:window.sessionStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});cloud.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){cloudUser=null;cloudRole=null;try{sessionStorage.removeItem(ADMIN_ACTIVITY_KEY);}catch{}if(ui.modal?.type==='admin'){ui.modal=null;$('#modalRoot').innerHTML='';render();}}});}await refreshCloudUser();bindAdminSessionMonitor();await loadCloud();}catch{cloudLoadStatus='error';if(stat)stat.textContent='Falha na conexão com a nuvem';render();}}
let leetifyTestBusy=false,leetifyTestResult='';
async function testLeetify(){
 if(leetifyTestBusy)return;
 if(!cloud||!canEdit()){leetifyTestResult='Erro de autenticação: entre como owner ou editor.';if(ui.modal?.type==='admin'&&ui.adminTab==='external')renderModal();return;}
 leetifyTestBusy=true;leetifyTestResult='Consultando o jogador configurado...';if(ui.modal?.type==='admin'&&ui.adminTab==='external')renderModal();
 try{
  const {data,error}=await cloud.functions.invoke('leetify-profile',{body:{}});
  if(error){
   const status=error.context?.status;
   if(status===401||status===403)leetifyTestResult='Erro de autenticação ou permissão. Entre novamente como owner ou editor.';
   else if(status===429)leetifyTestResult='Limite de requisições atingido. Aguarde pelo menos um minuto antes de tentar novamente.';
   else if(status===404)leetifyTestResult='Função ou jogador de teste não encontrado. Verifique a publicação e o ID configurado.';
   else if(status===422)leetifyTestResult='Não foi possível consultar o jogador configurado. Verifique o SteamID64 cadastrado.';
   else leetifyTestResult='Falha de comunicação ou configuração. Verifique a função e tente novamente.';
  }else if(data?.available===true)leetifyTestResult='Conexão realizada. Perfil encontrado.';
  else if(data?.available===false)leetifyTestResult='Conexão realizada. Perfil indisponível.';
  else leetifyTestResult='Falha de comunicação: resposta inesperada da função.';
 }catch{leetifyTestResult='Falha de comunicação. Verifique a conexão e tente novamente.';}
 finally{leetifyTestBusy=false;if(ui.modal?.type==='admin'&&ui.adminTab==='external')renderModal();}
}

