const draftMax=()=>db.draft.teams.length*Math.max(0,db.draft.maxPlayers-1);
const isDraftDone=()=>db.draft.log.length>=draftMax()&&draftMax()>0;
function nextTeam(){if(db.draft.status!=='live'||isDraftDone())return null;const n=db.draft.teams.length,round=Math.floor(db.draft.log.length/n),position=db.draft.log.length%n;return db.draft.teams[db.draft.snake&&round%2===1?n-1-position:position];}
