function standings(group){
 const teams=db.draft.teams.filter(t=>String(t.group||'A').toUpperCase()===group);
 return teams.map(t=>{
   let s={team:t,j:0,v:0,d:0,pts:0,rf:0,rs:0,sg:0};
   playedMatches().filter(m=>m.stage==='groups'&&String(m.group||'A').toUpperCase()===group&&(m.teamA===t.id||m.teamB===t.id)).forEach(m=>{
     const own=m.teamA===t.id, ownScore=own?Number(m.scoreA):Number(m.scoreB), oppScore=own?Number(m.scoreB):Number(m.scoreA);
     s.j++;s.rf+=ownScore;s.rs+=oppScore;if(ownScore>oppScore){s.v++;s.pts+=3;}else{s.d++;}
   });s.sg=s.rf-s.rs;return s;
 }).sort((a,b)=>b.pts-a.pts||b.v-a.v||b.sg-a.sg||b.rf-a.rf||a.team.name.localeCompare(b.team.name,'pt-BR'));
}
function officialStats(playerId){
 const entries=[];
 for(const m of playedMatches()){
   const item=(m.playerStats||[]).find(x=>x.playerId===playerId);
   if(!item)continue;
   const rounds=Number(item.roundsPlayed)||0;
   const teamId=m.teamA===item.teamId||m.teamB===item.teamId?item.teamId:(rosterOf(teamById(m.teamA)||{}).some(p=>p.id===playerId)?m.teamA:m.teamB);
   entries.push({...item,match:m,rounds,won:teamId===m.teamA?Number(m.scoreA)>Number(m.scoreB):Number(m.scoreB)>Number(m.scoreA)});
 }
 const games=entries.length,kills=entries.reduce((x,v)=>x+Number(v.kills||0),0),deaths=entries.reduce((x,v)=>x+Number(v.deaths||0),0),assists=entries.reduce((x,v)=>x+Number(v.assists||0),0),wins=entries.filter(e=>e.won).length;
 const adrEntries=entries.filter(v=>v.adr!==null&&v.adr!==undefined&&v.adr!==''&&v.rounds>0),adrRounds=adrEntries.reduce((n,v)=>n+v.rounds,0);
 const adr=adrRounds?adrEntries.reduce((n,v)=>n+Number(v.adr)*v.rounds,0)/adrRounds:null;
 const hsEntries=entries.filter(v=>v.headshots!==null&&v.headshots!==undefined&&v.headshots!==''),hsKills=hsEntries.reduce((n,v)=>n+Number(v.kills||0),0),headshots=hsEntries.reduce((n,v)=>n+Number(v.headshots||0),0);
 return {games,maps:games,kills,deaths,assists,wins,winrate:games?wins/games*100:null,kd:games?(deaths?kills/deaths:(kills?Infinity:0)):null,adr,headshots:hsEntries.length?headshots:null,hs:hsKills?headshots/hsKills*100:null};
}
function officialRanking(){return db.players.map(p=>({p,s:officialStats(p.id)})).filter(x=>x.s.games>0).sort((a,b)=>(b.s.kd??0)-(a.s.kd??0)||(b.s.adr??0)-(a.s.adr??0)||b.s.kills-a.s.kills||a.p.nick.localeCompare(b.p.nick,'pt-BR'));}
function officialPosition(id){const n=officialRanking().findIndex(x=>x.p.id===id);return n<0?null:n+1;}
const numberOrDash=(n,d=0)=>n===null||n===undefined?'—':fmt(n,d);
const percentOrDash=(n)=>n===null||n===undefined?'—':fmt(n,0)+'%';
function groupChip(g){return `<span class="group-chip">GRUPO ${esc(g)}</span>`;}
function renderStandingsRows(g){const rows=standings(g);return rows.map((s,i)=>`<tr><td><span class="stand-pos">${i+1}</span></td><td><div class="table-team-identity"><span class="table-team-badge" style="--teamcolor:${esc(s.team.color||'#c0fb5b')}">${esc(s.team.tag||'TM')}</span><strong>${esc(s.team.name)}</strong></div></td><td><strong>${s.pts}</strong></td><td>${s.j}</td><td>${s.v}</td><td>${s.d}</td><td>${s.rf}</td><td>${s.rs}</td><td><span class="${s.sg>0?'score-positive':s.sg<0?'score-negative':''}">${s.sg>0?'+':''}${s.sg}</span></td></tr>`).join('')||'<tr><td colspan="9">Nenhuma equipe neste grupo.</td></tr>';}
function renderStandings(){const groups=groupList().filter(g=>ui.tableGroup==='Todos'||ui.tableGroup===g);const groupMatches=playedMatches().filter(m=>m.stage==='groups');const total=groupMatches.length;return `<div class="page-intro"><div><span class="eyebrow">CAMPEONATO / CLASSIFICAÇÃO</span><h1 class="heading">TABELA <span>DE GRUPOS</span></h1><p class="subheading">Atualizada automaticamente pelos placares finalizados da fase de grupos. Vitória: 3 pontos · derrota: 0.</p></div>${canEdit()?`<button class="btn btn-primary" data-action="open-admin-matches">${ico('plus')} REGISTRAR PARTIDA</button>`:''}</div><section class="competition-strip"><div><small>PARTIDAS FINALIZADAS</small><strong>${total}</strong></div><div><small>GRUPOS</small><strong>${groupList().length}</strong></div><div><small>EQUIPES</small><strong>${db.draft.teams.length}</strong></div><p>Critérios de desempate: pontos, vitórias, saldo de rounds e rounds pró. Sem resultados fictícios.</p></section><div class="competition-filter">${['Todos',...groupList()].map(g=>`<button class="role-btn ${ui.tableGroup===g?'active':''}" data-group="${esc(g)}">${g==='Todos'?'TODOS OS GRUPOS':'GRUPO '+esc(g)}</button>`).join('')}</div><div class="standings-grid">${groups.map(g=>`<section class="standings-card"><header>${groupChip(g)}<span>${standings(g).length} TIMES</span></header><div class="table-scroll"><table class="data-table competition-table"><thead><tr><th>#</th><th>TIME</th><th>PTS</th><th>J</th><th>V</th><th>D</th><th>RP</th><th>RC</th><th>SR</th></tr></thead><tbody>${renderStandingsRows(g)}</tbody></table></div></section>`).join('')||emptyState('Sem grupos','Cadastre times e defina seus grupos na área administrativa.')}</div><div class="competition-footnote">PTS = pontos · J = jogos · V = vitórias · D = derrotas · RP = rounds pró · RC = rounds contra · SR = saldo de rounds. Apenas partidas finalizadas da fase de grupos entram na classificação. No celular, deslize a tabela para os lados para ver todas as colunas.</div><div class="standings-next"><div><span class="eyebrow">AGENDA E RESULTADOS</span><h2 class="heading">PARTIDAS <span>DO CAMPEONATO</span></h2></div><button class="btn" data-route="history">${ico('arrow')} VER TODAS AS PARTIDAS</button></div>${renderMatchCards(db.competition.matches.slice().sort(sortMatches).slice(0,6))}</div>`;}
function sortMatches(a,b){return String(b.date||'').localeCompare(String(a.date||''))||String(a.id).localeCompare(String(b.id));}
function renderMatchCards(matches){return matches.length?`<div class="match-grid">${matches.map(m=>{const tA=teamById(m.teamA),tB=teamById(m.teamB);return `<article class="fixture-card"><div class="fixture-top"><span>${m.stage==='playoffs'?'PLAYOFFS':`GRUPO ${esc(m.group||'A')}`} · ${esc(m.map||'MAPA A DEFINIR')}</span><span class="${m.status==='finished'?'fixture-finished':'fixture-scheduled'}">${m.status==='finished'?'FINALIZADA':m.status==='cancelled'?'CANCELADA':m.status==='cancelled'?'CANCELADA':'AGENDADA'}</span></div><div class="fixture-scoreline"><div class="fixture-team"><span class="fixture-emblem" style="--teamcolor:${esc(tA?.color||'#aabbcc')}">${esc(tA?.tag||'?')}</span><strong>${esc(tA?.name||'Time removido')}</strong></div><div class="fixture-result">${m.status==='finished'?`<strong>${Number(m.scoreA)} <em>:</em> ${Number(m.scoreB)}</strong>`:'<strong class="fixture-vs">VS</strong>'}<small>${matchDate(m)}</small></div><div class="fixture-team right"><span class="fixture-emblem" style="--teamcolor:${esc(tB?.color||'#aabbcc')}">${esc(tB?.tag||'?')}</span><strong>${esc(tB?.name||'Time removido')}</strong></div></div></article>`;}).join('')}</div>`:emptyState('Nenhuma partida cadastrada','Quando a organização cadastrar os confrontos, eles aparecerão aqui.');}
const externalSourceStats=(p,source)=>p.externalStats?.[source]||null;
function leetifyProfileUrl(p){
 const id=typeof p.steamId64==='string'?p.steamId64.trim():'';
 if(/^\d{17}$/.test(id))return `https://leetify.com/app/profile/${id}`;
 for(const value of [p.steamUrl,p.steamProfileUrl]){
  if(typeof value!=='string')continue;
  try{const url=new URL(value.trim());const match=url.pathname.match(/^\/profiles\/(\d{17})\/?$/);if(['http:','https:'].includes(url.protocol)&&['steamcommunity.com','www.steamcommunity.com'].includes(url.hostname.toLowerCase())&&match)return `https://leetify.com/app/profile/${match[1]}`;}catch{}
 }
 const existing=p.externalStats?.leetify?.profileUrl;
 if(typeof existing==='string')try{const url=new URL(existing.trim());if(url.protocol==='https:'&&url.hostname.toLowerCase()==='leetify.com'&&/^\/app\/profile\/\d{17}\/?$/.test(url.pathname))return `https://leetify.com${url.pathname.replace(/\/$/,'')}`;}catch{}
 return '';
}
const externalMetric=(stats,key,d=0)=>stats&&stats[key]!==null&&stats[key]!==undefined?fmt(stats[key],d):'SEM DADOS';
const SCOUT_PRESENTATION={
 kd:{label:'K/D',group:'performance',format:'ratio',threshold:'kd'},adr:{label:'ADR',group:'performance',format:'decimal',threshold:'adr'},winrate:{label:'Win Rate',group:'performance',format:'percent',threshold:'winrate'},kast:{label:'KAST',group:'performance',format:'percentDecimal',threshold:'kast'},hs:{label:'HS%',group:'performance',format:'percentDecimal'},hltvRating2Last81Games:{label:'HLTV Rating 2.0',group:'performance',format:'ratio',threshold:'hltv'},hltvRating2:{label:'HLTV Rating 2.0',group:'performance',format:'ratio',threshold:'hltv'},hltvRating:{label:'HLTV Rating 2.0',group:'performance',format:'ratio',threshold:'hltv'},
 premier:{label:'Premier atual',group:'rankings',format:'integer',premier:true},premierRating:{label:'Premier atual',group:'rankings',format:'integer',premier:true},premierSeason5Peak:{label:'Pico Premier — Temporada 5',group:'rankings',format:'integer',premier:true},faceit:{label:'Nível FACEIT',group:'rankings',format:'integer'},faceitLevel:{label:'Nível FACEIT',group:'rankings',format:'integer'},faceitElo:{label:'Elo FACEIT',group:'rankings',format:'integer'},gc:{label:'Nível Gamers Club',group:'rankings',format:'integer'},gcLevel:{label:'Nível Gamers Club',group:'rankings',format:'integer'},gcPoints:{label:'Pontos Gamers Club',group:'rankings',format:'integer'},
 games:{label:'Partidas analisadas',group:'additional',format:'integer'},kdAdrSampleGames:{label:'Partidas analisadas (K/D e ADR)',group:'additional',format:'integer'},winrateSampleGames:{label:'Partidas analisadas (Win Rate)',group:'additional',format:'integer'},winsInWinrateSample:{label:'Vitórias',group:'additional',format:'integer'},premierSeason5Games:{label:'Partidas Premier — Temporada 5',group:'additional',format:'integer'},premierSeason5WinratePercent:{label:'Win Rate Premier — Temporada 5',group:'additional',format:'percent'},wins:{label:'Vitórias',group:'additional',format:'integer'},losses:{label:'Derrotas',group:'additional',format:'integer'},draws:{label:'Empates',group:'additional',format:'integer'},faceitGames:{label:'Partidas FACEIT',group:'additional',format:'integer'},gcGames:{label:'Partidas Gamers Club',group:'additional',format:'integer'}
};
const SCOUT_THRESHOLDS={kd:{low:0.8,high:1.1},adr:{low:60,high:80},winrate:{low:45,high:55},kast:{low:60,high:70},hltv:{low:0.8,high:1.1}};
const PREMIER_BANDS=[{min:30000,name:'gold'},{min:25000,name:'red'},{min:20000,name:'pink'},{min:15000,name:'purple'},{min:10000,name:'blue'},{min:5000,name:'lightblue'},{min:0,name:'gray'}];
function scoutingNumber(value){if(value===null||value===undefined||typeof value==='boolean'||(typeof value!=='number'&&typeof value!=='string')||(typeof value==='string'&&!value.trim()))return null;const n=Number(value);return Number.isFinite(n)?n:null;}
function scoutingLabel(key){if(Object.hasOwn(SCOUT_PRESENTATION,key))return SCOUT_PRESENTATION[key].label;const s=String(key).replace(/([a-z\d])([A-Z])/g,'$1 $2').replace(/([A-Z])([A-Z][a-z])/g,'$1 $2').replace(/[_-]+/g,' ').trim();return s?s[0].toLocaleUpperCase('pt-BR')+s.slice(1):'Métrica';}
function scoutingFormat(key,value){const n=scoutingNumber(value);if(n===null)return 'SEM DADOS';const type=SCOUT_PRESENTATION[key]?.format||'auto';let min=0,max=2;if(type==='integer')max=0;else if(type==='ratio')min=max=2;else if(type==='decimal'||type==='percentDecimal')min=max=1;else if(type==='percent')max=1;const number=n.toLocaleString('pt-BR',{minimumFractionDigits:min,maximumFractionDigits:max});return number+(['percent','percentDecimal'].includes(type)?'%':'');}
function scoutingClass(key,value){const n=scoutingNumber(value),meta=SCOUT_PRESENTATION[key];if(n===null||!meta)return 'scout-neutral';if(meta.premier){if(n<0)return 'scout-neutral';return 'premier-'+(PREMIER_BANDS.find(b=>n>=b.min)?.name||'gray');}const t=SCOUT_THRESHOLDS[meta.threshold];return !t?'scout-neutral':n<t.low?'scout-low':n>t.high?'scout-high':'scout-neutral';}
function scoutingEntries(metrics){if(!metrics||typeof metrics!=='object')return [];const entries=Object.entries(metrics).filter(([k])=>k!=='extras');const extra=metrics.extras&&typeof metrics.extras==='object'&&!Array.isArray(metrics.extras)?Object.entries(metrics.extras):[];const seen=new Set(entries.map(([key])=>key));return [...entries,...extra.filter(([key])=>!seen.has(key))].filter(([,value])=>scoutingNumber(value)!==null);}
function scoutingMetricValue(metrics,key){return scoutingEntries(metrics).find(([name])=>name===key)?.[1];}
function scoutingSample(metrics,key){const sampleKey=key==='kd'||key==='adr'?'kdAdrSampleGames':key==='winrate'?'winrateSampleGames':null;if(!sampleKey)return '';const n=scoutingNumber(scoutingMetricValue(metrics,sampleKey));return n===null?'':`${scoutingFormat(sampleKey,n)} partidas analisadas`;
}
const TIER_ORDER=['S','A','B','C','D','E'];
function playerTier(p){const value=String(p.tier||'').trim().toUpperCase().replace(/^TIER\s*/,'');return TIER_ORDER.includes(value)?value:null;}
function scoutingKey(record){return JSON.stringify([record.source,record.period,record.mode]);}
function scoutingSets(){const sets=new Map();for(const p of db.players)for(const s of Array.isArray(p.scoutingAnalyses)?p.scoutingAnalyses:[]){if(s&&s.origin==='manual'&&!s.archived&&s.source&&s.period&&s.mode)sets.set(scoutingKey(s),s);}return [...sets.entries()].sort((a,b)=>a[0].localeCompare(b[0],'pt-BR'));}
function activeScoutingKey(){const sets=scoutingSets();return sets.some(([key])=>key===ui.scoutingKey)?ui.scoutingKey:(sets[0]?.[0]||'');}
function rosterExternalStats(p){const key=activeScoutingKey();return key?(p.scoutingAnalyses||[]).find(s=>s.origin==='manual'&&!s.archived&&scoutingKey(s)===key)?.metrics||null:null;}
function rosterExternalValue(p,key){return scoutingNumber(scoutingMetricValue(rosterExternalStats(p),key));}
function compareExternal(a,b,key){const av=rosterExternalValue(a,key),bv=rosterExternalValue(b,key);if(av===null&&bv===null)return a.nick.localeCompare(b.nick,'pt-BR');if(av===null)return 1;if(bv===null)return -1;return bv-av||a.nick.localeCompare(b.nick,'pt-BR');}
function rosterFiltered(){const query=ui.q.trim().toLocaleLowerCase('pt-BR');const arr=db.players.slice().filter(p=>ui.role==='Todos'||p.role===ui.role).filter(p=>ui.tier==='Todos'||playerTier(p)===ui.tier).filter(p=>(`${p.nick} ${p.name} ${p.role} ${p.flag}`).toLocaleLowerCase('pt-BR').includes(query));if(ui.sort==='nick-desc')arr.sort((a,b)=>b.nick.localeCompare(a.nick,'pt-BR'));else if(ui.sort==='tier')arr.sort((a,b)=>(TIER_ORDER.indexOf(playerTier(a))<0?TIER_ORDER.length:TIER_ORDER.indexOf(playerTier(a)))-(TIER_ORDER.indexOf(playerTier(b))<0?TIER_ORDER.length:TIER_ORDER.indexOf(playerTier(b)))||a.nick.localeCompare(b.nick,'pt-BR'));else if(ui.sort==='kd'||ui.sort==='winrate')arr.sort((a,b)=>compareExternal(a,b,ui.sort));else arr.sort((a,b)=>a.nick.localeCompare(b.nick,'pt-BR'));return arr;}
function scoutingCardSamples(metrics){const kd=scoutingMetricValue(metrics,'kdAdrSampleGames'),win=scoutingMetricValue(metrics,'winrateSampleGames');const parts=[];if(scoutingNumber(kd)!==null)parts.push('K/D e ADR: '+scoutingFormat('kdAdrSampleGames',kd)+' partidas');if(scoutingNumber(win)!==null)parts.push('Win Rate: '+scoutingFormat('winrateSampleGames',win)+' partidas');return parts.length?`<small class="card-scouting-samples">${esc(parts.join(' · '))}</small>`:'';}
function shortScoutingSource(value){const source=typeof value==='string'?value.trim():'';return source&&source.length<=22?`Scouting · ${source}`:'Scouting';}
function renderPlayerCard(p){const t=selectedTeam(p.id),source=rosterExternalStats(p),analysis=(p.scoutingAnalyses||[]).find(s=>s.origin==='manual'&&!s.archived&&scoutingKey(s)===activeScoutingKey());return `<article class="player-card ${t?'selected':''}" data-glow="${esc(p.nick)}" style="--glow:${['#81c979','#7eaef2','#d2a168','#b39de8'][hash(p.nick)%4]}" data-profile="${esc(p.id)}" role="button" tabindex="0" aria-label="Abrir perfil de ${esc(p.nick)}"><div class="card-topline"><div class="rank-number">${p.tier?`<span>TIER</span> ${esc(p.tier)}`:'<span>SCOUTING</span>'}</div>${t?`<span class="status-pill captain">${esc(t.tag)}</span>`:''}</div>${portrait(p,'player-art')}<div class="card-main"><h3 class="player-nick">${esc(p.nick)}</h3>${p.name?`<div class="player-realname">${esc(p.flag||'')} ${esc(p.name)}</div>`:''}<span class="card-role">${esc(p.role)}</span>${analysis?`<small class="card-source">${esc(shortScoutingSource(analysis.source))}</small>`:''} </div><div class="card-footer"><div class="card-stats">${['kd','adr','winrate','games'].map(key=>`<span><strong class="${scoutingClass(key,scoutingMetricValue(source,key))}">${scoutingNumber(scoutingMetricValue(source,key))===null?'—':esc(scoutingFormat(key,scoutingMetricValue(source,key)))}</strong>${key==='games'?'PARTIDAS':key==='kd'?'K/D GERAL':key==='adr'?'ADR GERAL':'WIN RATE'}</span>`).join('')}</div><span class="card-open" aria-hidden="true">${ico('arrow')}</span></div></article>`;}
function renderPlayers(){return `${renderHomeNews()}<section class="roster-intro"><div><span class="eyebrow">${esc(db.eventName)} / ELENCO OFICIAL</span><h1 class="heading">JOGADORES <span>DO CAMPEONATO</span></h1><p class="subheading">Scouting baseado em dados externos verificados. Estatísticas oficiais são exibidas apenas na Tabela MVP e no perfil de cada jogador.</p></div><button class="btn btn-ghost" data-route="standings">${ico('trophy')} TABELA DE GRUPOS</button></section><div class="roster-tools"><div class="section-controls"><label class="search-input">${ico('search')}<input id="rosterSearch" value="${esc(ui.q)}" placeholder="Buscar jogador..." aria-label="Buscar jogador"></label><select id="rosterTier" class="select roster-tier" aria-label="Filtrar por Tier"><option value="Todos" ${ui.tier==='Todos'?'selected':''}>Todos os Tiers</option>${TIER_ORDER.map(t=>`<option value="${t}" ${ui.tier===t?'selected':''}>Tier ${t}</option>`).join('')}</select><select id="rosterSort" class="select roster-sort" aria-label="Ordenar jogadores"><option value="nick-asc" ${ui.sort==='nick-asc'?'selected':''}>Nome A–Z</option><option value="nick-desc" ${ui.sort==='nick-desc'?'selected':''}>Nome Z–A</option><option value="tier" ${ui.sort==='tier'?'selected':''}>Melhor Tier (S até E)</option><option value="kd" ${ui.sort==='kd'?'selected':''}>K/D geral (maior primeiro)</option><option value="winrate" ${ui.sort==='winrate'?'selected':''}>Win Rate geral (maior primeiro)</option></select><button type="button" class="btn btn-ghost btn-clear-filters" data-action="clear-roster-filters" ${(ui.q||ui.role!=='Todos'||ui.tier!=='Todos'||ui.sort!=='nick-asc')?'':'disabled'}>${ico('undo')} LIMPAR</button></div></div><div class="filter-row"><div class="role-filters">${['Todos',...ROLES].map(r=>`<button class="role-btn ${ui.role===r?'active':''}" data-role="${esc(r)}">${esc(r)}</button>`).join('')}</div><span class="result-count" id="rosterCount">${rosterFiltered().length} JOGADORES</span></div><div class="scouting-picker"><label for="scoutingSet">ANÁLISE DE SCOUTING</label><select id="scoutingSet" class="select" ${scoutingSets().length?'':'disabled'}>${scoutingSets().length?scoutingSets().map(([key,s])=>`<option value="${esc(key)}" ${key===activeScoutingKey()?'selected':''}>${esc([s.source,s.period,s.mode].join(" · "))}</option>`).join(''):'<option>Sem análises disponíveis</option>'}</select><span>Ordenação compara somente a análise selecionada; sem dados ficam no fim.</span></div><section id="playersGrid" class="players-grid">${rosterFiltered().map(renderPlayerCard).join('')||(db.players.length?emptyState('Nenhum jogador encontrado','Tente mudar a busca ou os filtros.'):emptyState('Nenhum jogador cadastrado','Os jogadores aparecerão aqui quando forem cadastrados.'))}</section>`;}
function emptyState(title,description){return `<div class="empty-state" style="grid-column:1/-1">${ico('search')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function refreshRoster(){const players=rosterFiltered();if($('#playersGrid'))$('#playersGrid').innerHTML=players.map(renderPlayerCard).join('')||emptyState('Nenhum jogador encontrado','Tente mudar a busca ou os filtros.');if($('#rosterCount'))$('#rosterCount').textContent=`${players.length} ${players.length===1?'JOGADOR':'JOGADORES'}`;const clear=$('[data-action="clear-roster-filters"]');if(clear)clear.disabled=!(ui.q||ui.role!=='Todos'||ui.tier!=='Todos'||ui.sort!=='nick-asc');}
function renderDraftPlayer(p){return `<div class="draft-player-row">${portrait(p,'draft-avatar')}<div class="draft-name"><strong>${esc(p.nick)} <span class="muted">#${p.rank}</span></strong><small>${esc(p.role)} · K/D ${fmt(p.kd)}</small></div><div class="draft-row-score">${p.faceit}<small>FACEIT</small></div><button class="btn btn-sm ${db.draft.status==='live'?'btn-primary':''}" data-pick="${esc(p.id)}" ${db.draft.status!=='live'?'disabled':''}>${ico('plus')} ESCOLHER</button></div>`;}
function renderTeam(team){const members=rosterOf(team),active=nextTeam()?.id===team.id;return `<section class="team-panel ${active?'active-team':''}" style="--teamcolor:${esc(team.color)}"><header class="team-header"><div class="team-logo">${esc(team.tag.slice(0,1))}</div><div><h3>${esc(team.name)}</h3><small>${members.length}/${db.draft.maxPlayers} jogadores ${active?'· É SUA VEZ':''}</small></div></header><div class="team-roster">${Array.from({length:db.draft.maxPlayers},(_,i)=>{const p=members[i];return `<div class="team-slot ${p?'':'empty-slot'}"><span class="slot-index">${String(i+1).padStart(2,'0')}</span>${p?`${portrait(p,'slot-photo')}<div style="min-width:0;flex:1"><strong>${esc(p.nick)}</strong><small>${esc(p.role)}</small></div>${i===0?'<span class="captain-star" title="Capitão">★</span>':''}`:`<span>Vaga disponível</span>`}</div>`;}).join('')}</div></section>`;}
function draftValidation(){if(db.draft.teams.length<2)return 'Configure pelo menos 2 times.';const ids=db.draft.teams.map(t=>t.captainId);if(ids.some(id=>!id||!byId(id)))return 'Defina um capitão válido para cada time no painel do organizador.';if(new Set(ids).size!==ids.length)return 'Cada capitão só pode comandar um time.';if(db.draft.maxPlayers<2)return 'O tamanho do time deve ser pelo menos 2.';if(db.players.length<db.draft.teams.length*db.draft.maxPlayers)return `São necessários ${db.draft.teams.length*db.draft.maxPlayers} jogadores para preencher todos os times; há apenas ${db.players.length}.`;return null;}
function renderDraft(){const cur=nextTeam(),setup=db.draft.status==='setup',complete=db.draft.status==='complete',free=db.players.filter(p=>!drafted(p.id)).sort((a,b)=>a.rank-b.rank),validation=draftValidation();return `<div class="page-intro"><div><span class="eyebrow">CAPITÃES NO COMANDO</span><h1 class="heading">DRAFT <span>AO VIVO</span></h1><p class="subheading">O organizador controla as escolhas na ordem dos capitães. Cada escolha atualiza os times.</p></div><button class="btn" data-action="open-admin-draft">${ico('settings')} CONFIGURAR TIMES</button></div><section class="draft-stage"><div><small>${setup?'PRONTO PARA COMEÇAR':complete?'SELEÇÃO FINALIZADA':'CAPITÃO DA VEZ'}</small><strong>${setup?'ARENA PRONTA':complete?'DRAFT CONCLUÍDO':esc(cur?.name||'—')}</strong><p>${setup?'Confira os capitães e inicie o draft.':complete?'Todos os times foram preenchidos.':`Escolha ${db.draft.log.length+1} de ${draftMax()} · ${db.draft.snake?'Ordem snake':'Ordem circular'}`}</p></div><div class="draft-stage-controls">${setup?`<button class="btn btn-primary" data-action="start-draft" ${validation?'disabled':''}>${ico('bolt')} INICIAR DRAFT</button>`:`<button class="btn btn-ghost" data-action="undo-pick" ${!db.draft.log.length?'disabled':''}>${ico('undo')} DESFAZER</button>`}<button class="btn ${setup?'':'btn-warn'}" data-action="reset-draft">${ico('history')} REINICIAR</button><button class="btn btn-ghost" data-action="export-teams">${ico('download')} EXPORTAR</button></div></section>${setup&&validation?`<div class="notice warning">${ico('info')}${esc(validation)} <button class="btn btn-sm" data-action="open-admin-draft">Configurar</button></div>`:''}${setup?`<div class="notice">${ico('info')} Os cabeças de chave já ocupam uma vaga em seus respectivos times. O draft usa as demais vagas. Para mudar os capitães, abra “Configurar times”.</div>`:''}${complete?`<div class="notice">${ico('check')} Todas as escolhas concluídas. Exporte a lista de times ou reinicie para uma nova rodada.</div>`:''}<div class="draft-layout"><div><h2 class="section-label">${ico('users')} JOGADORES DISPONÍVEIS <span class="tag muted">${free.length}</span></h2><div class="draft-players">${free.length?free.map(renderDraftPlayer).join(''):emptyState('Elenco completo','Não há mais jogadores livres para escolher.')}</div></div><div><h2 class="section-label">${ico('shield')} TIMES EM FORMAÇÃO</h2><div class="team-grid">${db.draft.teams.map(renderTeam).join('')}</div><div class="log-panel"><strong style="font-size:12px">${ico('history')} HISTÓRICO DE ESCOLHAS</strong><div class="pick-log">${db.draft.log.length?db.draft.log.map((entry,i)=>`<div class="pick-item"><em>${String(i+1).padStart(2,'0')}</em> ${esc(byId(entry.playerId)?.nick||'—')} <span class="muted">Ã¢â€ ’ ${esc(db.draft.teams.find(t=>t.id===entry.teamId)?.tag||'—')}</span></div>`).join(''):'<span class="muted" style="font-size:11px">As escolhas aparecerão aqui.</span>'}</div></div></div></div>`;}
function rankRows(){let rows=db.players.map(p=>({p,s:officialStats(p.id)})).filter(({p})=>(`${p.nick} ${p.name} ${p.role}`).toLowerCase().includes(ui.rankQ.toLowerCase())).filter(({p})=>ui.rankTeam==='Todos'||selectedTeam(p.id)?.id===ui.rankTeam);if(ui.rankSort!=='provisional'){const key=ui.rankSort;rows.sort((a,b)=>{if(!a.s.games||!b.s.games)return a.s.games-b.s.games;const av=key==='team'?selectedTeam(a.p.id)?.name:key==='nick'?a.p.nick:a.s[key],bv=key==='team'?selectedTeam(b.p.id)?.name:key==='nick'?b.p.nick:b.s[key];if(typeof av==='string'||typeof bv==='string')return String(bv||'').localeCompare(String(av||''),'pt-BR')||a.p.nick.localeCompare(b.p.nick,'pt-BR');return (Number(bv??-Infinity)-Number(av??-Infinity))||a.p.nick.localeCompare(b.p.nick,'pt-BR');});}else{const positions=new Map(officialRanking().map((x,i)=>[x.p.id,i]));rows.sort((a,b)=>a.s.games&&b.s.games?positions.get(a.p.id)-positions.get(b.p.id):a.s.games?-1:b.s.games?1:a.p.nick.localeCompare(b.p.nick,'pt-BR'));}return rows;}
function renderRankTable(){const positions=new Map(officialRanking().map((x,i)=>[x.p.id,i+1]));return rankRows().map(({p,s})=>{const pos=positions.get(p.id),team=selectedTeam(p.id);return `<tr class="${pos&&pos<=3?'mvp-top-'+pos:''} ${pos?'':'mvp-no-stats'}"><td><span class="rank-big ${pos&&pos<=3?'top3':''}">${pos?'#'+String(pos).padStart(2,'0'):'—'}</span></td><td><div class="table-person" data-profile="${esc(p.id)}" role="button" tabindex="0" style="cursor:pointer">${portrait(p)}<div><strong>${esc(p.nick)}</strong><small>${esc(p.name)}</small></div></div></td><td>${esc(team?.name||'Sem time')}</td><td><strong>${numberOrDash(s.kd,2)}</strong></td><td>${numberOrDash(s.adr,1)}</td><td>${s.games?s.kills:'—'}</td><td>${s.games?s.deaths:'—'}</td><td>${s.games?s.assists:'—'}</td><td>${s.games}</td><td>${s.maps||'—'}</td><td>${s.games?numberOrDash(s.headshots):'—'}</td><td>${percentOrDash(s.hs)}</td><td><button class="btn btn-sm btn-ghost" data-profile="${esc(p.id)}">${ico('eye')} PERFIL</button></td></tr>`;}).join('')||'<tr><td colspan="13">Nenhum jogador corresponde aos filtros.</td></tr>';}
function renderRanking(){const teams=[...new Map(db.players.map(p=>selectedTeam(p.id)).filter(Boolean).map(t=>[t.id,t])).values()];return `<div class="page-intro"><div><span class="eyebrow">ESTATÍSTICAS OFICIAIS / VANTA ARENA</span><h1 class="heading">TABELA <span>MVP</span></h1><p class="subheading">Todos os inscritos e somente dados de partidas finalizadas do campeonato.</p></div>${canEdit()?`<button class="btn btn-primary" data-action="open-admin-matches">${ico('plus')} REGISTRAR ESTATÍSTICAS</button>`:''}</div><div class="mvp-toolbar"><label class="search-input">${ico('search')}<input id="rankingSearch" value="${esc(ui.rankQ)}" placeholder="Buscar nickname..."></label><select id="rankingTeam" class="select" aria-label="Filtrar por time"><option value="Todos">Todos os times</option>${teams.map(t=>`<option value="${esc(t.id)}" ${ui.rankTeam===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><label class="mvp-sort-label">Ordenar <select id="rankingSort" class="select"><option value="provisional" ${ui.rankSort==='provisional'?'selected':''}>Ordem provisória</option><option value="kd" ${ui.rankSort==='kd'?'selected':''}>K/D</option><option value="adr" ${ui.rankSort==='adr'?'selected':''}>ADR</option><option value="kills" ${ui.rankSort==='kills'?'selected':''}>Kills</option><option value="deaths" ${ui.rankSort==='deaths'?'selected':''}>Deaths</option><option value="assists" ${ui.rankSort==='assists'?'selected':''}>Assists</option><option value="maps" ${ui.rankSort==='maps'?'selected':''}>Mapas</option><option value="headshots" ${ui.rankSort==='headshots'?'selected':''}>Headshots</option><option value="hs" ${ui.rankSort==='hs'?'selected':''}>HS%</option><option value="winrate" ${ui.rankSort==='winrate'?'selected':''}>Win rate</option></select></label><span class="tag muted">${officialRanking().length} COM ESTREIA</span></div><div class="mvp-order-note">Ordem provisória: K/D, ADR disponível e kills, em caráter informativo. Não representa pontuação oficial do campeonato. ADR considera apenas registros com rounds jogados informados.</div><section class="ranking-wrap"><div class="table-scroll"><table class="data-table mvp-table"><thead><tr><th>POS.</th><th><button class="mvp-sort" type="button" data-rank-sort="nick">JOGADOR</button></th><th><button class="mvp-sort" type="button" data-rank-sort="team">TIME ATUAL</button></th><th><button class="mvp-sort" type="button" data-rank-sort="kd">K/D</button></th><th><button class="mvp-sort" type="button" data-rank-sort="adr">ADR MÉDIO</button></th><th><button class="mvp-sort" type="button" data-rank-sort="kills">K</button></th><th><button class="mvp-sort" type="button" data-rank-sort="deaths">D</button></th><th><button class="mvp-sort" type="button" data-rank-sort="assists">A</button></th><th><button class="mvp-sort" type="button" data-rank-sort="games">PARTIDAS</button></th><th><button class="mvp-sort" type="button" data-rank-sort="maps">MAPAS</button></th><th><button class="mvp-sort" type="button" data-rank-sort="headshots">HS</button></th><th><button class="mvp-sort" type="button" data-rank-sort="hs">HS%</button></th><th>PERFIL</th></tr></thead><tbody id="rankingBody">${renderRankTable()}</tbody></table></div></section><div class="competition-footnote">Ã¢â‚¬Â  Posição provisória somente entre quem já estreou. Médias de ADR usam a soma de ADR × rounds jogados dividida pelo total de rounds informados. HS% = headshots ÷ kills nos mapas com os dois dados. Em celular, deslize a tabela horizontalmente.</div>`;}
function allMatches(){return db.competition.matches.slice().filter(m=>`${teamById(m.teamA)?.name||''} ${teamById(m.teamB)?.name||''} ${m.map||''} ${m.group||''}`.toLowerCase().includes(ui.historyQ.toLowerCase())).filter(m=>ui.matchFilter==='Todos'||(ui.matchFilter==='finished'?m.status==='finished':m.status==='scheduled')).sort(sortMatches);}
function historyRows(){return allMatches().map(m=>`<tr><td>${matchDate(m)}</td><td>${m.stage==='groups'?groupChip(m.group||'A'):'PLAYOFFS'}</td><td><strong>${teamLabel(m.teamA)}</strong> <span class="muted">vs</span> <strong>${teamLabel(m.teamB)}</strong></td><td>${esc(m.map||'—')}</td><td><span class="tag ${m.status==='finished'?'':m.status==='cancelled'?'cancelled':'muted'}">${m.status==='finished'?'FINALIZADA':m.status==='cancelled'?'CANCELADA':m.status==='cancelled'?'CANCELADA':'AGENDADA'}</span></td><td><strong class="match-score">${m.status==='finished'?`${Number(m.scoreA)} : ${Number(m.scoreB)}`:'— : —'}</strong></td><td>${(m.playerStats||[]).length?`${m.playerStats.length} JOGADORES`:'—'}</td></tr>`).join('')||'<tr><td colspan="7">Nenhuma partida encontrada.</td></tr>';}
function renderHistory(){return `<div class="page-intro"><div><span class="eyebrow">RESULTADOS OFICIAIS / CAMPEONATO</span><h1 class="heading">PARTIDAS <span>DO CAMP</span></h1><p class="subheading">Jogos agendados, resultados e estatísticas individuais. Resultados da fase de grupos atualizam a tabela automaticamente.</p></div>${canEdit()?`<button class="btn btn-primary" data-action="open-admin-matches">${ico('plus')} REGISTRAR PARTIDA</button>`:''}</div><div class="history-top"><label class="search-input">${ico('search')}<input id="historySearch" value="${esc(ui.historyQ)}" placeholder="Time, mapa ou grupo..."></label><div class="competition-filter">${[['Todos','TODAS'],['scheduled','AGENDADAS'],['finished','FINALIZADAS']].map(([v,label])=>`<button class="role-btn ${ui.matchFilter===v?'active':''}" data-match-filter="${v}">${label}</button>`).join('')}</div></div><div id="historyListContent">${renderMatchCards(allMatches())}</div><div class="standings-next"><h2 class="heading">TODOS OS <span>REGISTROS</span></h2><button class="btn" data-route="standings">${ico('trophy')} VER CLASSIFICAÇÃO</button></div><div class="history-wrap"><div class="table-scroll"><table class="data-table"><thead><tr><th>DATA</th><th>FASE</th><th>CONFRONTO</th><th>MAPA</th><th>STATUS</th><th>PLACAR</th><th>STATS</th></tr></thead><tbody id="historyBody">${historyRows()}</tbody></table></div></div>`;}
let homeCarouselTimer=null,homeCarouselStart=0,homeCarouselElapsed=0,homeCarouselIndex=0,homeCarouselPaused=false,homeCarouselPointer=null;
const HOME_CAROUSEL_MS=5000;
function stopHomeCarousel(){if(homeCarouselTimer){clearInterval(homeCarouselTimer);homeCarouselTimer=null;}homeCarouselPointer=null;}
function homeNews(){return publishedNews().slice(0,4);}
function renderHomeNews(){const list=homeNews();if(!list.length)return `<section class="home-news-empty"><span class="eyebrow">JORNAL DA ARENA / ÚLTIMAS NOTÍCIAS</span><div><span class="home-news-mark">VANTA<span>.</span></span><h2>AS HISTÓRIAS DA ARENA<br><em>COMEÇAM AQUI.</em></h2><p>Em breve, novidades do campeonato e da comunidade.</p><button class="btn btn-ghost" data-route="news">VISITAR O JORNAL ${ico('arrow')}</button></div></section>`;const slides=list.map((a,i)=>`<article class="home-news-slide ${i===0?'active':''}" data-home-slide="${i}" aria-hidden="${i!==0}"><div class="home-news-photo">${photoForArticle(a,'',false)}</div><div class="home-news-shade"></div><div class="home-news-copy"><span class="news-category">${esc(a.category||'COMUNIDADE')} <i>ï¼</i> JORNAL DA ARENA</span><h2>${esc(a.title)}</h2><p>${esc(a.summary)}</p><div class="news-meta">${articleDate(a)} · ${esc(a.author||'REDAÇÃO')}</div><button type="button" class="btn btn-primary home-news-read" data-article="${esc(a.id)}">LER NOTÍCIA ${ico('arrow')}</button></div><button type="button" class="home-news-hit" data-article="${esc(a.id)}" aria-label="Ler notícia: ${esc(a.title)}"></button></article>`).join('');return `<section class="home-news" aria-label="Notícias recentes do Jornal da Arena" data-home-carousel><div class="home-news-top"><div><span class="eyebrow">JORNAL DA ARENA / EM DESTAQUE</span><h2>ÚLTIMAS <span>NOTÍCIAS</span></h2></div><button class="home-news-all" data-route="news">VER TODAS ${ico('arrow')}</button></div><div class="home-news-viewport" tabindex="0" aria-roledescription="carrossel" aria-label="Notícias em destaque">${slides}${list.length>1?`<div class="home-news-arrows"><button type="button" data-home-step="-1" aria-label="Notícia anterior">‹</button><button type="button" data-home-step="1" aria-label="Próxima notícia">›</button></div><div class="home-news-progress" role="tablist" aria-label="Selecionar notícia">${list.map((a,i)=>`<button type="button" class="home-news-indicator ${i===0?'active':''}" data-home-goto="${i}" role="tab" aria-label="Notícia ${i+1}: ${esc(a.title)}" aria-selected="${i===0}"><span><i></i></span></button>`).join('')}</div><span class="home-news-count"><b>01</b> / ${String(list.length).padStart(2,'0')}</span>`:''}</div></section>`;}
function setupHomeCarousel(){stopHomeCarousel();const root=$('[data-home-carousel]');if(!root)return;const slides=[...root.querySelectorAll('[data-home-slide]')],indicators=[...root.querySelectorAll('[data-home-goto]')],viewport=root.querySelector('.home-news-viewport');if(slides.length<2)return;homeCarouselIndex=0;homeCarouselElapsed=0;homeCarouselPaused=false;const paint=()=>{slides.forEach((el,i)=>{el.classList.toggle('active',i===homeCarouselIndex);el.setAttribute('aria-hidden',String(i!==homeCarouselIndex));});indicators.forEach((el,i)=>{el.classList.toggle('active',i===homeCarouselIndex);el.setAttribute('aria-selected',String(i===homeCarouselIndex));});const count=root.querySelector('.home-news-count');if(count)count.innerHTML=`<b>${String(homeCarouselIndex+1).padStart(2,'0')}</b> / ${String(slides.length).padStart(2,'0')}`;root.style.setProperty('--news-progress',`${Math.min(100,homeCarouselElapsed/HOME_CAROUSEL_MS*100)}%`);};const go=(index,manual=false)=>{homeCarouselIndex=(index+slides.length)%slides.length;if(manual)homeCarouselElapsed=0;paint();};root.addEventListener('click',e=>{const step=e.target.closest('[data-home-step]'),goto=e.target.closest('[data-home-goto]');if(step)go(homeCarouselIndex+Number(step.dataset.homeStep),true);if(goto)go(Number(goto.dataset.homeGoto),true);});root.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;homeCarouselPointer={id:e.pointerId,x:e.clientX,y:e.clientY};});root.addEventListener('pointerup',e=>{if(!homeCarouselPointer||e.pointerId!==homeCarouselPointer.id)return;const dx=e.clientX-homeCarouselPointer.x,dy=e.clientY-homeCarouselPointer.y;homeCarouselPointer=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2)go(homeCarouselIndex+(dx<0?1:-1),true);});root.addEventListener('pointercancel',()=>{homeCarouselPointer=null;});root.addEventListener('keydown',e=>{if(e.target!==viewport)return;if(e.key==='ArrowRight'){e.preventDefault();go(homeCarouselIndex+1,true);}if(e.key==='ArrowLeft'){e.preventDefault();go(homeCarouselIndex-1,true);}});const pause=()=>{homeCarouselPaused=true;};const resume=()=>{homeCarouselPaused=false;};root.addEventListener('mouseenter',pause);root.addEventListener('mouseleave',resume);root.addEventListener('focusin',pause);root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget))resume();});root.addEventListener('touchstart',pause,{passive:true});root.addEventListener('touchend',resume,{passive:true});homeCarouselTimer=setInterval(()=>{if(homeCarouselPaused)return;homeCarouselElapsed+=80;if(homeCarouselElapsed>=HOME_CAROUSEL_MS){homeCarouselElapsed=0;go(homeCarouselIndex+1);}else paint();},80);paint();}
function photoForArticle(a,cls='',showPlaceholderLabels=true){return a.imageUrl&&safeSrc(a.imageUrl)?`<img class="${cls}" src="${esc(a.imageUrl)}" alt="Capa da matéria: ${esc(a.title)}" loading="lazy">`:`<div class="news-placeholder ${cls}" aria-hidden="true">${showPlaceholderLabels?'<span>VANTA<span class="lime">/</span></span><strong>PRESS</strong><small>CS2 • CAMPEONATO</small>':''}</div>`;}
function newsCard(a,i){return `<article class="news-card" data-article="${esc(a.id)}" role="button" tabindex="0"><div class="news-card-media">${photoForArticle(a)}</div><div class="news-card-copy"><span class="news-category">${esc(a.category||'COMUNIDADE')}</span><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><div class="news-meta"><span>${articleDate(a)} · ${esc(a.author||'REDAÇÃO')}</span><span>LER MATÉRIA Ã¢â€ —</span></div></div></article>`;}
function renderNews(){const list=publishedNews(),feature=list[0];return `<section class="newspaper-head"><div><span class="eyebrow">O LADO B DO CAMPEONATO</span><h1 class="paper-masthead">JORNAL <em>DA ARENA<span>.</span></em></h1><p>Clutches, bastidores, rivalidades saudáveis e as melhores resenhas do servidor.</p></div><div class="paper-stamp"><strong>VANTA</strong><small>EDIÇÃO DIGITAL</small><span>EST. 2026</span></div></section><div class="paper-ticker"><span>ÚLTIMAS DO SERVIDOR</span><p>Notícias, avisos oficiais e histórias da comunidade. Sem fake news e com muito CS.</p></div>${feature?`<section class="news-feature" data-article="${esc(feature.id)}" role="button" tabindex="0"><div class="news-feature-image">${photoForArticle(feature)}</div><div class="news-feature-copy"><span class="news-category">DESTAQUE / ${esc(feature.category)}</span><h2>${esc(feature.title)}</h2><p>${esc(feature.summary)}</p><div class="news-meta">${articleDate(feature)} · ${esc(feature.author||'REDAÇÃO')}</div><span class="read-link">CONTINUAR LENDO Ã¢â€ ’</span></div></section>`:emptyState('A redação está preparando a primeira edição','Nenhuma matéria publicada ainda.')}<div class="news-section-head"><div><span class="eyebrow">ARQUIVO DA REDAÇÃO</span><h2 class="heading">ÚLTIMAS <span>MATÉRIAS</span></h2></div>${canEdit()?`<button class="btn btn-primary" data-action="open-admin-news">${ico('plus')} NOVA MATÉRIA</button>`:''}</div><section class="news-grid">${list.slice(1).map(newsCard).join('')||'<p class="subheading">Novas histórias em breve.</p>'}</section>`;}
function openArticle(id){if(!articleById(id)||!publishedNews().find(a=>a.id===id))return;ui.articleId=id;ui.route='article';ui.modal=null;$('#modalRoot').innerHTML='';render();location.hash='noticia/'+encodeURIComponent(id);window.scrollTo({top:0,behavior:'instant'});}
function renderArticlePage(a){if(!a)return emptyState('Matéria não encontrada','Volte ao Jornal para consultar as notícias.');return `<div class="article-page"><button class="btn btn-ghost" data-route="news">Ã¢â€  VOLTAR AO JORNAL</button><div class="article-heading"><span class="news-category">${esc(a.category)}</span><h1>${esc(a.title)}</h1><p>${esc(a.summary)}</p><div class="news-meta">${articleDate(a)} · POR ${esc(a.author||'REDAÇÃO')}</div></div><div class="article-cover">${photoForArticle(a)}</div><div class="article-body">${esc(a.body||'').split(/\n{2,}/).filter(Boolean).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('')}</div>${canEdit()?`<button class="btn" data-action="edit-article" data-id="${esc(a.id)}">${ico('settings')} EDITAR MATÉRIA</button>`:''}</div>`;}
function renderTeams(){return `<div class="page-intro"><div><span class="eyebrow">ELENCOS OFICIAIS</span><h1 class="heading">TIMES DO <span>CAMPEONATO</span></h1><p class="subheading">A organização registra os elencos depois da escolha dos capitães. Novos times podem ser adicionados ao campeonato.</p></div>${canEdit()?`<button class="btn btn-primary" data-action="open-admin-teams">${ico('plus')} ADICIONAR / EDITAR TIMES</button>`:''}</div><div class="mini-info-bar">${db.draft.teams.length} TIMES CADASTRADOS <span>·</span> ${groupList().length} GRUPOS <button data-route="standings" class="btn btn-sm btn-ghost">VER TABELA ${ico('arrow')}</button></div><section class="published-teams">${db.draft.teams.length?db.draft.teams.map(t=>`<section class="published-team" style="--teamcolor:${esc(t.color||'#c0fb5b')}"><div class="published-team-top"><div class="team-logo">${esc((t.tag||'?')[0])}</div><div><h2>${esc(t.name)}</h2><small>${esc(t.tag)} · GRUPO ${esc(t.group||'A')} · ${rosterOf(t).length} jogador(es)</small></div></div><div class="published-roster">${rosterOf(t).map((p,i)=>`<div class="published-player" data-profile="${esc(p.id)}" role="button" tabindex="0">${portrait(p,'slot-photo')}<div><strong>${esc(p.nick)}</strong><small>${i===0?'CAPITÃO · ':''}${esc(p.role)}</small></div><span>${officialPosition(p.id)===null?'—':'#'+officialPosition(p.id)}</span></div>`).join('')||'<p class="subheading">Elenco ainda não registrado.</p>'}</div></section>`).join(''):emptyState('Times em preparação','A organização publicará os elencos após o draft.')}</section>`;}
function renderLogin(){return `<div class="modal-overlay" data-close-overlay="1"><article class="modal login-modal" role="dialog" aria-modal="true" aria-label="Acesso da equipe"><button class="modal-close" data-action="close-modal" aria-label="Fechar">${ico('close')}</button><div class="admin-header"><span class="eyebrow">ACESSO RESTRITO</span><h2>ENTRAR NA REDAÇÃO</h2><p>Use o usuário da equipe e a senha da conta técnica autorizada.</p></div><div class="admin-content"><form id="loginForm"><div class="field"><label>Usuário</label><input name="username" type="text" autocomplete="username" required value="camp2026" placeholder="camp2026" autocapitalize="none" spellcheck="false"></div><div class="field" style="margin-top:12px"><label>Senha</label><input name="password" type="password" autocomplete="current-password" required minlength="6"></div><div class="form-actions"><button class="btn btn-primary" type="submit">ENTRAR NO PAINEL</button></div></form><p class="field-help">Acesso restrito ÃƒÂ  organização. O e-mail técnico do Supabase não é exibido nesta tela.</p></div></article></div>`;}
function renderAdminAccount(){return `<div class="data-zone"><div><h4>STATUS DA EQUIPE</h4><p>${cloudConfigured?`Conectado: ${esc(cloudUser?.email||'—')} · Permissão: ${esc(cloudRole||'não autorizado')}`:'Você está visualizando um protótipo local. Para cadastrar administradores de verdade, configure o Supabase conforme o README.'}</p></div>${cloudConfigured?`<button class="btn btn-warn" data-action="logout">SAIR DA CONTA</button>`:''}</div><div class="settings-note">Visitantes não precisam entrar. O login só é usado por quem edita as informações do campeonato.</div>`;}
function renderAdminNews(){const a=articleById(ui.editingArticleId),all=articles.slice().sort((a,b)=>String(b.publishedAt).localeCompare(String(a.publishedAt)));return `<div class="admin-players"><aside><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><b>MATÉRIAS (${all.length})</b><button class="btn btn-sm btn-primary" data-action="new-article">${ico('plus')} NOVA</button></div><div class="admin-list">${all.map(x=>`<button class="admin-list-item ${a?.id===x.id?'active':''}" data-admin-article="${esc(x.id)}"><span><strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${x.status==='published'?'PUBLICADA':'RASCUNHO'}</small></span></button>`).join('')||'<p class="field-help">Nenhuma matéria ainda.</p>'}</div></aside><div><form id="articleForm"><div class="form-grid"><div class="form-section-name">${a?'EDITAR MATÉRIA':'CRIAR MATÉRIA'}</div><div class="field span2"><label>Título *</label><input name="title" maxlength="130" required value="${esc(a?.title||'')}" placeholder="Ex.: Capitães aquecem o mercado da bala"></div><div class="field"><label>Categoria</label><select name="category">${['BASTIDORES','COMUNIDADE','ENTREVISTA','RESULTADOS','AVISO OFICIAL','MERCADO DA BALA','MEMES'].map(x=>`<option ${a?.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field full"><label>Resumo (chamada) *</label><textarea name="summary" maxlength="280" rows="2" required placeholder="Uma chamada curta e chamativa...">${esc(a?.summary||'')}</textarea></div><div class="field full"><label>Texto da matéria *</label><textarea name="body" rows="10" required placeholder="Conte sua história. Separe parágrafos com uma linha em branco.">${esc(a?.body||'')}</textarea></div><div class="field span2"><label>Imagem de capa (URL https://)</label><input name="imageUrl" value="${esc(a?.imageUrl||'')}" placeholder="https://...jpg"></div><div class="field"><label>Assinatura</label><input name="author" maxlength="60" value="${esc(a?.author||'Redação VANTA')}"></div><div class="field"><label>Publicação</label><select name="status"><option value="draft" ${a?.status==='draft'?'selected':''}>Salvar rascunho</option><option value="published" ${a?.status==='published'?'selected':''}>Publicar no jornal</option></select></div></div><div class="form-actions">${a?`<button type="button" class="btn btn-warn" data-action="delete-article" data-id="${esc(a.id)}">EXCLUIR</button>`:''}<button type="submit" class="btn btn-primary">${ico('check')} ${a?'SALVAR EDIÇÃO':'SALVAR MATÉRIA'}</button></div></form></div></div>`;}
function renderAdminTeams(){const d=db.draft;const opts=selected=>`<option value="">— Não definido —</option>${db.players.slice().sort((a,b)=>a.nick.localeCompare(b.nick)).map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.nick)}</option>`).join('')}`;return `<div class="notice">${ico('info')} Adicione times conforme o campeonato crescer. Defina o GRUPO de cada equipe (A, B, C...). Apenas partidas dos times dentro do mesmo grupo contam para a tabela daquela chave.</div><form id="teamsForm"><div class="form-grid"><div class="field span2"><label>Nome do campeonato</label><input name="eventName" value="${esc(db.eventName)}" maxlength="44"></div><div class="field"><label>Quantidade de times (até 32)</label><input name="teamCount" type="number" min="1" max="32" value="${d.teams.length}"></div><div class="field"><label>Jogadores por time</label><select name="maxPlayers">${[2,3,4,5,6,7,8,9,10].map(x=>`<option ${x===d.maxPlayers?'selected':''} value="${x}">${x} jogadores</option>`).join('')}</select></div></div><div class="config-teams">${d.teams.map((t,i)=>`<div class="config-team"><h4>TIME ${String(i+1).padStart(2,'0')}</h4><div class="field"><label>Nome do time</label><input name="teamName_${i}" value="${esc(t.name)}" maxlength="36"></div><div class="field"><label>Sigla</label><input name="teamTag_${i}" value="${esc(t.tag)}" maxlength="4"></div><div class="field"><label>Grupo (A, B, C...)</label><input name="teamGroup_${i}" value="${esc(t.group||'A')}" maxlength="3" placeholder="A"></div>${Array.from({length:d.maxPlayers},(_,j)=>`<div class="field"><label>${j===0?'Capitão':`Jogador ${j+1}`}</label><select name="slot_${i}_${j}">${opts(rosterOf(t)[j]?.id||'')}</select></div>`).join('')}</div>`).join('')}</div><div class="form-actions"><button class="btn" type="button" data-action="add-team">${ico('plus')} ADICIONAR NOVO TIME</button><button class="btn btn-primary" type="submit">${ico('check')} SALVAR TIMES</button></div><p class="field-help">O botão adiciona imediatamente um time vazio. Você também pode alterar a quantidade e salvar. Para não perder resultados oficiais, a remoção de um time com partidas cadastradas será bloqueada.</p></form>`;}
async function submitNewsForm(form){if(!canEdit())return toast('Você precisa ser editor.',true);const fd=new FormData(form);const title=String(fd.get('title')||'').trim().slice(0,130),summary=String(fd.get('summary')||'').trim().slice(0,280),body=String(fd.get('body')||'').trim().slice(0,15000),url=String(fd.get('imageUrl')||'').trim();if(!title||!summary||!body)return toast('Preencha título, chamada e texto.',true);if(url&&!/^https:\/\//i.test(url))return toast('A imagem precisa ser uma URL https://.',true);const old=articleById(ui.editingArticleId),post={id:old?.id||'news_'+Date.now()+'_'+Math.random().toString(36).slice(2,8),title,summary,body,category:String(fd.get('category')||'COMUNIDADE').slice(0,50),imageUrl:url,author:String(fd.get('author')||'Redação').trim().slice(0,60),status:fd.get('status')==='published'?'published':'draft',publishedAt:old?.publishedAt||new Date().toISOString()};try{if(cloudConfigured)await cloudSaveArticle(post);if(old)Object.assign(old,post);else articles.unshift(post);saveNewsLocal();ui.editingArticleId=post.id;render();toast(post.status==='published'?'Matéria publicada!':'Rascunho salvo.');}catch(e){toast('Não foi possível salvar: '+e.message,true);}}
async function deleteArticle(id){if(!canEdit())return;if(!confirm('Excluir definitivamente esta matéria?'))return;try{if(cloudConfigured){const {error}=await cloud.from('news_posts').delete().eq('id',id);if(error)throw error;}articles=articles.filter(a=>a.id!==id);saveNewsLocal();ui.editingArticleId=articles[0]?.id||null;render();toast('Matéria excluída.');}catch(e){toast('Erro ao excluir: '+e.message,true);}}
function submitTeamsForm(form){if(!canEdit())return;const fd=new FormData(form),count=clamp(fd.get('teamCount'),1,32),max=clamp(fd.get('maxPlayers'),2,10),existing=db.draft.teams;const removed=existing.slice(count);if(db.competition.matches.some(m=>removed.some(t=>t.id===m.teamA||t.id===m.teamB)))return toast('Não é possível remover um time que já possui partidas. Exclua os confrontos antes.',true);const newTeams=Array.from({length:count},(_,i)=>{const old=existing[i]||{},ids=Array.from({length:max},(_,j)=>String(fd.get(`slot_${i}_${j}`)||'')).map(x=>byId(x)?x:'');return {id:old.id||uid(),name:String(fd.get(`teamName_${i}`)||old.name||`TIME ${i+1}`).trim().slice(0,36),tag:String(fd.get(`teamTag_${i}`)||old.tag||`T${i+1}`).trim().toUpperCase().slice(0,4),group:String(fd.get(`teamGroup_${i}`)||old.group||'A').trim().toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,3)||'A',color:old.color||['#c0fb5b','#62e1d2','#ffa15e','#bd91ff','#edda70','#78bcff'][i%6],captainId:ids[0]||'',members:ids.slice(1).filter(Boolean)};});const all=newTeams.flatMap(t=>[t.captainId,...t.members]).filter(Boolean);if(new Set(all).size!==all.length)return toast('Um jogador não pode aparecer em dois times ou posições.',true);if(db.competition.matches.some(m=>m.stage==='groups'&&m.status==='finished'&&newTeams.some(t=>(t.id===m.teamA||t.id===m.teamB)&&t.group!==m.group)))return toast('Um time com resultado finalizado não pode mudar de grupo. Edite ou exclua a partida antes.',true);db.draft.maxPlayers=max;db.draft.teams=newTeams;db.draft.log=newTeams.flatMap(t=>t.members.map(playerId=>({teamId:t.id,playerId,at:new Date().toISOString()})));db.draft.status='complete';db.eventName=String(fd.get('eventName')||db.eventName).trim().slice(0,44)||db.eventName;save();render();toast('Elencos e grupos salvos!');}
function matchStatsFields(teamId,existing){const team=teamById(teamId);if(!team)return '';const roster=rosterOf(team);if(!roster.length)return `<p class="field-help">${esc(team.name)} ainda não possui jogadores cadastrados.</p>`;return `<section class="match-player-team"><h4>${esc(team.name)} <span>${esc(team.tag)}</span></h4><div class="match-player-head"><span>JOGADOR</span><span>KILLS</span><span>DEATHS</span><span>ASSISTS</span><span>ADR</span><span>ROUNDS</span><span>HS</span></div>${roster.map(player=>{const st=(existing?.playerStats||[]).find(x=>x.playerId===player.id)||{};return `<div class="match-player-inputs"><strong>${esc(player.nick)}</strong>${[['kills',st.kills],['deaths',st.deaths],['assists',st.assists],['adr',st.adr],['roundsPlayed',st.roundsPlayed],['headshots',st.headshots]].map(([k,v])=>`<input type="number" min="0" max="${k==='adr'?400:k==='roundsPlayed'?100:200}" step="${k==='adr'?'0.1':'1'}" name="ps_${esc(player.id)}_${k}" value="${v===undefined||v===null?'':esc(v)}" placeholder="—" aria-label="${esc(k)} de ${esc(player.nick)}">`).join('')}</div>`;}).join('')}</section>`;}
function renderMatchPlayers(teamA,teamB,existing){return `<div class="match-stats-head"><h4>ESTATÍSTICAS INDIVIDUAIS <span>OPCIONAIS</span></h4><p>Preencha K/D/A, ADR, rounds jogados e HS (headshot kills). Se ADR for informado, rounds jogados também é obrigatório. Deixe todos os campos em branco para quem não participou. Sem stats a partida conta somente na Tabela de Grupos.</p></div>${teamA&&teamB&&teamA!==teamB?matchStatsFields(teamA,existing)+matchStatsFields(teamB,existing):'<p class="field-help">Selecione dois times diferentes para inserir as estatísticas dos jogadores.</p>'}`;}
function renderAdminMatches(){const editing=db.competition.matches.find(m=>m.id===ui.editingMatchId)||null,groups=groupList();const teamOptions=(id)=>`<option value="">Selecione</option>${db.draft.teams.map(t=>`<option value="${esc(t.id)}" ${t.id===id?'selected':''}>${esc(t.name)} · ${esc(t.group||'A')}</option>`).join('')}`;return `<div class="notice">${ico('info')} PLACAR DE GRUPOS ATUALIZA A TABELA DE GRUPOS. ESTATISTICAS INDIVIDUAIS ATUALIZAM A TABELA MVP E OS PERFIS. PLAYOFFS NAO ALTERAM A TABELA DE GRUPOS.</div><div class="admin-match-layout"><div><div class="admin-list-header"><strong>CONFRONTOS (${db.competition.matches.length})</strong><button type="button" class="btn btn-primary btn-sm" data-action="new-match">${ico('plus')} NOVO</button></div><div class="admin-match-list">${db.competition.matches.slice().sort(sortMatches).map(m=>`<button class="admin-match-item ${editing?.id===m.id?'active':''}" type="button" data-edit-match="${esc(m.id)}"><strong>${teamLabel(m.teamA)} × ${teamLabel(m.teamB)}</strong><small>${matchDate(m)} · ${m.status==='finished'?`${Number(m.scoreA)} : ${Number(m.scoreB)}`:m.status==='cancelled'?'CANCELADA':'AGENDADA'} · ${m.stage==='groups'?'GRUPO '+esc(m.group):'PLAYOFFS'}</small></button>`).join('')||'<p class="field-help">Nenhum confronto cadastrado.</p>'}</div></div><div><form id="matchForm"><div class="form-section-name">${editing?'EDITAR PARTIDA':'CADASTRAR NOVA PARTIDA'}</div><div class="form-grid"><div class="field"><label>Fase</label><select name="stage" id="matchStage"><option value="groups" ${(!editing||editing.stage==='groups')?'selected':''}>Fase de grupos</option><option value="playoffs" ${editing?.stage==='playoffs'?'selected':''}>Playoffs</option></select></div><div class="field"><label>Grupo</label><select name="group" id="matchGroup">${groups.map(g=>`<option value="${esc(g)}" ${g===(editing?.group||groups[0])?'selected':''}>Grupo ${esc(g)}</option>`).join('')||'<option value="A">A</option>'}</select></div><div class="field"><label>Time A</label><select name="teamA" id="matchTeamA" required>${teamOptions(editing?.teamA)}</select></div><div class="field"><label>Time B</label><select name="teamB" id="matchTeamB" required>${teamOptions(editing?.teamB)}</select></div><div class="field"><label>Data</label><input name="date" type="date" value="${esc(editing?.date||new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10))}"></div><div class="field"><label>Mapa</label><select name="map">${['A definir',...MAPS].map(n=>`<option value="${esc(n)}" ${n===(editing?.map||'A definir')?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status" id="matchStatus"><option value="scheduled" ${(!editing||editing.status==='scheduled')?'selected':''}>Agendada</option><option value="finished" ${editing?.status==='finished'?'selected':''}>Finalizada (contar resultado)</option><option value="cancelled" ${editing?.status==='cancelled'?'selected':''}>Cancelada</option></select></div><div class="field"><label>Observação (opcional)</label><input name="notes" maxlength="140" placeholder="Ex.: rodada 1" value="${esc(editing?.notes||'')}"></div><div class="field"><label>Rounds do Time A</label><input type="number" min="0" max="100" step="1" name="scoreA" value="${editing?.status==='finished'?esc(editing.scoreA):''}" placeholder="13"></div><div class="field"><label>Rounds do Time B</label><input type="number" min="0" max="100" step="1" name="scoreB" value="${editing?.status==='finished'?esc(editing.scoreB):''}" placeholder="9"></div></div><div id="matchPlayerStats" class="match-stats-editor">${renderMatchPlayers(editing?.teamA,editing?.teamB,editing)}</div><div class="form-actions">${editing?`<button type="button" class="btn btn-warn" data-action="delete-match" data-id="${esc(editing.id)}">${ico('trash')} EXCLUIR</button>`:''}<button class="btn btn-primary" type="submit">${ico('check')} ${editing?'SALVAR PARTIDA':'CADASTRAR PARTIDA'}</button></div></form></div></div>`;}
function updateMatchPlayerFields(){const area=$('#matchPlayerStats'),form=$('#matchForm');if(!area||!form)return;const match=db.competition.matches.find(m=>m.id===ui.editingMatchId);area.innerHTML=renderMatchPlayers(form.elements.teamA.value,form.elements.teamB.value,match);}
function submitMatch(form){if(!canEdit())return toast('Acesso de editor necessário.',true);const f=new FormData(form);const a=String(f.get('teamA')||''),b=String(f.get('teamB')||''),ta=teamById(a),tb=teamById(b),stage=String(f.get('stage')),group=String(f.get('group')||'A'),status=String(f.get('status')||'scheduled');if(!ta||!tb||a===b)return toast('Selecione dois times diferentes.',true);if(stage==='groups'&&(ta.group!==group||tb.group!==group))return toast('Na fase de grupos, os dois times precisam pertencer ao grupo selecionado.',true);const va=f.get('scoreA'),vb=f.get('scoreB');if(status==='finished'&&(va===''||vb===''||!/^\d+$/.test(String(va))||!/^\d+$/.test(String(vb))||Number(va)===Number(vb)))return toast('Para finalizar, informe um placar válido sem empate.',true);const existing=db.competition.matches.find(m=>m.id===ui.editingMatchId),playerStats=[];if(status==='finished')for(const team of [ta,tb])for(const player of rosterOf(team)){
 const vals=['kills','deaths','assists','adr','roundsPlayed','headshots'].map(key=>f.get(`ps_${player.id}_${key}`));if(vals.every(v=>v===null||String(v).trim()===''))continue;
 if(vals.slice(0,3).some(v=>v===null||String(v).trim()===''))return toast(`Informe K, D e A para ${player.nick}, ou deixe os 6 campos em branco.`,true);
 const [kills,deaths,assists,adr,roundsPlayed,headshots]=vals.map(v=>v===null||String(v).trim()===''?null:Number(v));if(vals.some((v,i)=>v!==null&&String(v).trim()!==''&&(!Number.isFinite(Number(v))||Number(v)<0))||headshots!==null&&headshots>kills||adr!==null&&(!roundsPlayed||roundsPlayed<1)||roundsPlayed!==null&&roundsPlayed>Number(va)+Number(vb))return toast(`Estatísticas inválidas para ${player.nick}. Informe rounds jogados para calcular ADR.`,true);
 playerStats.push({playerId:player.id,teamId:team.id,kills,deaths,assists,adr,roundsPlayed,headshots});
 }
 const record={id:existing?.id||uid(),stage,group,status,teamA:a,teamB:b,date:String(f.get('date')||''),map:String(f.get('map')||'A definir').slice(0,30),scoreA:status==='finished'?Number(va):null,scoreB:status==='finished'?Number(vb):null,notes:String(f.get('notes')||'').slice(0,140),playerStats};
 if(existing)Object.assign(existing,record);else db.competition.matches.push(record);ui.editingMatchId=record.id;save();render();toast('Partida salva! Tabela de Grupos e Tabela MVP atualizadas automaticamente.');
}
function deleteMatch(id){if(!canEdit())return;const record=db.competition.matches.find(m=>m.id===id);if(!record||!confirm('Excluir a partida e remover os resultados da tabela/ranking?'))return;db.competition.matches=db.competition.matches.filter(m=>m.id!==id);ui.editingMatchId=null;save();render();toast('Partida excluída e classificação recalculada.');}
async function submitLogin(form){if(!cloud)return toast('Configure a nuvem primeiro.',true);const f=new FormData(form),username=String(f.get('username')||'').trim().toLowerCase(),technicalEmail=String(CLOUD_CONFIG.supabaseAdminEmail||'').trim(),password=String(f.get('password')||'');if(username!=='camp2026')return toast('Usuário inválido.',true);if(!technicalEmail||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(technicalEmail))return toast('Configure o e-mail técnico do Supabase em config.js.',true);try{sessionStorage.removeItem(ADMIN_ACTIVITY_KEY);}catch{}adminLastActivity=0;adminLastStored=0;const {error}=await cloud.auth.signInWithPassword({email:technicalEmail,password});if(error)return toast('Não foi possível entrar: '+error.message,true);await refreshCloudUser();if(!canEdit()){await cloud.auth.signOut({scope:'local'});await refreshCloudUser();return toast('Conta sem permissão editorial. Solicite acesso ao organizador.',true);}touchAdminSession(true);closeModal();await loadCloud();openAdmin('news');toast('Acesso autorizado.');}

function renderCloudLoading(){return cloudLoadStatus==='error'?'<section class="cloud-state" role="alert"><span class="eyebrow">CONEXÃO COM A NUVEM</span><h1 class="heading">NÃO FOI POSSÍVEL <span>CARREGAR</span></h1><p>Não foi possível carregar os dados do campeonato. Verifique sua conexão e tente novamente.</p><button type="button" class="btn btn-primary" data-action="retry-cloud">TENTAR NOVAMENTE</button></section>':'<section class="cloud-state" role="status" aria-live="polite"><span class="eyebrow">VANTA ARENA</span><h1 class="heading">CARREGANDO <span>JOGADORES</span></h1><p>Buscando os dados do campeonato...</p><div class="cloud-skeleton" aria-hidden="true"><span></span><span></span><span></span><span></span></div></section>';}
function render(){stopHomeCarousel();const titles={players:'INÍCIO',news:'JORNAL DA ARENA',article:'JORNAL',teams:'TIMES',standings:'TABELA',ranking:'TABELA MVP',history:'PARTIDAS',profile:byId(ui.playerId)?.nick?.toUpperCase()||'PERFIL'};$('#breadcrumbText').textContent=titles[ui.route]||'INÍCIO';$('#navPlayerCount').textContent=cloudLoadStatus==='ready'?db.players.length:'—';document.querySelector('.event-chip strong').textContent=db.eventName;document.querySelectorAll('[data-route].nav-link').forEach(n=>n.classList.toggle('active',n.dataset.route===(ui.route==='profile'?'players':ui.route==='article'?'news':ui.route)));$('#mainContent').innerHTML=cloudConfigured&&cloudLoadStatus!=='ready'?renderCloudLoading():ui.route==='profile'?renderProfilePage(byId(ui.playerId)):ui.route==='article'?renderArticlePage(articleById(ui.articleId)):({players:renderPlayers,news:renderNews,teams:renderTeams,standings:renderStandings,ranking:renderRanking,history:renderHistory}[ui.route]||renderPlayers)();if(ui.route==='players'&&cloudLoadStatus==='ready')setupHomeCarousel();if(ui.modal)renderModal();}
const ROUTE_HASH={players:'inicio',news:'jornal',teams:'times',standings:'tabela',ranking:'tabela-mvp',history:'partidas'};
function route(name){if(!['players','news','teams','standings','ranking','history'].includes(name))return;ui.route=name;ui.modal=null;$('#modalRoot').innerHTML='';$('#sidebar').classList.remove('mobile-open');render();if(location.hash.slice(1)!==ROUTE_HASH[name])location.hash=ROUTE_HASH[name];window.scrollTo({top:0,behavior:'instant'});}
function parseMatches(v){return String(v||'').split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const [date,map,result,kda,opponent,score]=line.split('|').map(s=>s?.trim()||'');const[k,d,a]=(kda||'').split('/').map(x=>clamp(x,0,100));return {date:date||'',map:map||'',result:/^[vVwW]/.test(result)?'V':'D',kills:k,deaths:d,assists:a,opponent:opponent||'',score:score||''};});}
function printMatches(matches){return (matches||[]).map(m=>`${m.date||''} | ${m.map||''} | ${m.result||'V'} | ${m.kills||0}/${m.deaths||0}/${m.assists||0} | ${m.opponent||''} | ${m.score||''}`).join('\n');}
function openProfile(id){if(!byId(id))return;ui.playerId=id;ui.route='profile';ui.modal=null;$('#modalRoot').innerHTML='';render();if(location.hash.slice(1)!==`jogador/${encodeURIComponent(id)}`)location.hash=`jogador/${encodeURIComponent(id)}`;window.scrollTo({top:0,behavior:'instant'});}
function openAdmin(tab='players',editId=ui.editingId){if(cloudConfigured&&!canEdit()){ui.modal={type:'login'};renderModal();return;}ui.playerFormDirty=false;individualStats=null;individualEdit=null;ui.modal={type:'admin'};ui.adminTab=tab;ui.editingId=editId||'new';ui.pendingPhoto=undefined;renderModal();}
function closeModal(){ui.modal=null;$('#modalRoot').innerHTML='';}
function renderModal(){let html=ui.modal?.type==='admin'?renderAdmin():ui.modal?.type==='login'?renderLogin():'';$('#modalRoot').innerHTML=html;}
function renderManualScouting(p){const analyses=Array.isArray(p.scoutingAnalyses)?p.scoutingAnalyses.filter(s=>s.origin==='manual'):[];return analyses.length?`<section class="profile-section"><h3>ANÁLISES MANUAIS</h3>${analyses.map(s=>{const entries=scoutingEntries(s.metrics),groups=[['performance','DESEMPENHO'],['rankings','RANKINGS'],['additional','INFORMAÇÕES ADICIONAIS']];const card=([key,value])=>{const sample=scoutingSample(s.metrics,key);return `<div class="profile-stat scout-stat"><small>${esc(scoutingLabel(key))}</small><strong class="${scoutingClass(key,value)}">${esc(scoutingFormat(key,value))}</strong>${sample?`<small class="scout-sample">${esc(sample)}</small>`:''}</div>`;};return `<div class="manual-analysis"><p><strong>${esc(s.source)}</strong> · ${esc(s.period)} · ${esc(s.mode)}${s.archived?' · HISTÓRICO':''}${s.analyzedAt?' · '+esc(s.analyzedAt):''}</p>${groups.map(([id,title])=>{const items=entries.filter(([key])=>(SCOUT_PRESENTATION[key]?.group||'additional')===id);if(!items.length)return '';return id==='additional'?`<details class="scout-details"><summary>${title} (${items.length})</summary><div class="profile-grid scout-secondary">${items.map(card).join('')}</div></details>`:`<div class="scout-group"><h4>${title}</h4><div class="profile-grid">${items.map(card).join('')}</div></div>`;}).join('')}</div>`;}).join('')}</section>`:'';}
function renderExternalSection(p){const sources=['leetify','csrep'].map(name=>{const s=externalSourceStats(p,name);return `<section class="profile-section"><h3>${name==='leetify'?'LEETIFY':'CSREP'}</h3>${s?`<div class="profile-grid"><div class="profile-stat"><small>K/D</small><strong class="${scoutingClass('kd',s.kd)}">${scoutingFormat('kd',s.kd)}</strong></div><div class="profile-stat"><small>ADR</small><strong class="${scoutingClass('adr',s.adr)}">${scoutingFormat('adr',s.adr)}</strong></div><div class="profile-stat"><small>WIN RATE</small><strong class="${scoutingClass('winrate',s.winrate)}">${scoutingFormat('winrate',s.winrate)}</strong></div><div class="profile-stat"><small>PARTIDAS ANALISADAS</small><strong>${scoutingFormat('games',s.games)}</strong></div></div><p>Período: ${esc(s.period||'não informado')} · Atualizado em: ${esc(s.updatedAt||'não informado')} · Fonte: ${esc(s.source||name)}</p>${s.profileUrl?`<a href="${esc(s.profileUrl)}" target="_blank" rel="noopener">Ver perfil ${name==='leetify'?'no Leetify':'no CSRep'}</a>`:''}`:'<p>Sem dados externos disponíveis para esta fonte.</p>'}</section>`;}).join('');return `<section class="profile-section"><h3 class="profile-section-title">DESEMPENHO GERAL</h3><p>Fontes permanecem separadas; métricas de uma fonte não completam nem recalculam a outra.</p>${renderManualScouting(p)}${sources}<div class="external-pill-row"><span>FACEIT <strong>${scoutingFormat('faceit',p.externalStats?.platforms?.faceit)}</strong></span><span>GAMERS CLUB <strong>${scoutingFormat('gc',p.externalStats?.platforms?.gc)}</strong></span><span>PREMIER <strong class="${scoutingClass('premier',p.externalStats?.platforms?.premier)}">${scoutingFormat('premier',p.externalStats?.platforms?.premier)}</strong></span></div>${leetifyProfileUrl(p)?`<a class="btn btn-ghost leetify-profile-link" href="${esc(leetifyProfileUrl(p))}" target="_blank" rel="noopener noreferrer" aria-label="Ver perfil de ${esc(p.nick)} na Leetify (abre em nova aba)">Ver na Leetify <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M13 5h6v6M19 5l-9 9"/><path d="M19 14v4a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h4"/></svg></a>`:''}<p>Histórico competitivo externo será exibido quando uma API autorizada o fornecer.</p></section>`;}
function profileContent(p){const t=selectedTeam(p.id),s=officialStats(p.id),pos=officialPosition(p.id);const history=playedMatches().filter(m=>(m.playerStats||[]).some(x=>x.playerId===p.id)).sort(sortMatches);return `<div class="profile-hero"><div class="profile-portrait">${portrait(p)}</div><div class="profile-head"><span class="eyebrow">PERFIL DO JOGADOR</span><h2>${esc(p.nick)}</h2><p>${esc(p.flag)} ${esc(p.name)}</p><div class="profile-pills"><span class="tag">${esc(p.role)}</span><span class="tag muted">${t?esc(t.name):'SEM TIME'}</span>${p.tier?`<span class="tag">TIER ${esc(p.tier)}</span>`:''}</div><div class="profile-rank">${pos===null?'SEM ESTREIA · SEM POSIÇÃO':`#${String(pos).padStart(2,'0')} · POSIÇÃO PROVISÓRIA`}</div></div></div><div class="profile-body">${renderExternalSection(p)}<h3 class="profile-section-title">DESEMPENHO NO CAMPEONATO</h3><div class="profile-grid"><div class="profile-stat"><small>K/D CAMP</small><strong>${numberOrDash(s.kd,2)}</strong></div><div class="profile-stat"><small>MAPAS</small><strong>${s.maps}</strong></div><div class="profile-stat"><small>ABATES</small><strong>${s.kills}</strong></div><div class="profile-stat"><small>MORTES</small><strong>${s.deaths}</strong></div><div class="profile-stat"><small>ASSISTÊNCIAS</small><strong>${s.assists}</strong></div><div class="profile-stat"><small>ADR CAMP</small><strong>${numberOrDash(s.adr,1)}</strong></div><div class="profile-stat"><small>HEADSHOTS</small><strong>${numberOrDash(s.headshots)}</strong></div><div class="profile-stat"><small>HS%</small><strong>${percentOrDash(s.hs)}</strong></div><div class="profile-stat"><small>WIN RATE CAMP</small><strong>${percentOrDash(s.winrate)}</strong></div></div><p class="field-help">ADR médio ponderado pelos rounds registrados por jogador. Dados antigos sem rounds informados não entram nesta média.</p><section class="profile-section"><h3>SCOUTING REPORT</h3><p>${esc(p.bio||'Nenhuma descrição cadastrada.')}</p></section><section class="profile-section"><h3>PARTIDAS OFICIAIS DO CAMPEONATO</h3><div class="profile-history">${history.length?history.map(m=>{const st=(m.playerStats||[]).find(x=>x.playerId===p.id);return `<div class="profile-match"><span class="date">${matchDate(m)}</span><strong>${esc(m.map||'—')}</strong><span>${teamLabel(m.teamA)} x ${teamLabel(m.teamB)}</span><span>${Number(m.scoreA)}:${Number(m.scoreB)}</span><span>${st.kills}/${st.deaths}/${st.assists}</span></div>`;}).join(''):'<p>Este jogador ainda não tem estatísticas cadastradas em partidas oficiais.</p>'}</div></section><div class="profile-actions">${canEdit()?`<button class="btn" data-action="edit-player" data-id="${esc(p.id)}">${ico('settings')} EDITAR PERFIL</button>`:''}<button class="btn btn-ghost" data-route="players">${ico('arrow')} VOLTAR AO ELENCO</button></div></div>`;}
function renderProfilePage(p){if(!p)return emptyState('Jogador não encontrado','Volte ao elenco para consultar os participantes.');return `<div class="page-intro"><div><span class="eyebrow">INTELIG&Ecirc;NCIA DE JOGO / SCOUTING</span><h1 class="heading">PLAYER <span>PROFILE</span></h1><p class="subheading">Dados oficiais do campeonato e informações externas do participante, claramente separadas.</p></div><button class="btn btn-ghost" data-route="players">&larr; TODOS OS JOGADORES</button></div><section class="profile-standalone" aria-label="Perfil do jogador ${esc(p.nick)}">${profileContent(p)}</section>`;}
function renderAdmin(){const tabs=[['players','JOGADORES'],['external','SCOUTING EXTERNO'],['news','REDAÇÃO / JORNAL'],['teams','TIMES'],['matches','PARTIDAS'],['data','DADOS'],['account','ACESSO']];return `<div class="modal-overlay" data-close-overlay="1"><article class="modal admin-modal" role="dialog" aria-modal="true" aria-label="Painel administrativo"><button class="modal-close" aria-label="Fechar" data-action="close-modal">${ico('close')}</button><header class="admin-header"><span class="eyebrow">${cloudConfigured?'ÁREA RESTRITA':'MODO DEMONSTRAÇÃO LOCAL'}</span><h2>PAINEL ADMINISTRATIVO</h2><p>Cadastre participantes, atualize scouting externo autorizado e registre partidas oficiais. ${cloudConfigured?'Dados compartilhados entre os editores autorizados.':'Sem nuvem: alterações ficam neste navegador; o painel não tem autenticação real.'}</p></header><div class="admin-tabs">${tabs.map(([id,name])=>`<button class="admin-tab ${ui.adminTab===id?'active':''}" data-admin-tab="${id}">${name}</button>`).join('')}</div><div class="admin-content">${ui.adminTab==='players'?renderAdminPlayers():ui.adminTab==='external'?renderAdminExternal():ui.adminTab==='news'?renderAdminNews():ui.adminTab==='teams'?renderAdminTeams():ui.adminTab==='matches'?renderAdminMatches():ui.adminTab==='account'?renderAdminAccount():renderAdminData()}</div></article></div>`;}
function renderAdminExternal(){return `<div class="notice">${ico('info')} O teste consulta somente o jogador configurado na função. Os dados da Leetify não são armazenados nem exibidos nos cards.</div><div class="data-zone"><div><h4>TESTE DE CONEXÃO</h4><p>Teste temporário para o jogador configurado pela organização.</p><p class="field-help" role="status" aria-live="polite">${esc(leetifyTestResult)}</p></div><button type="button" class="btn btn-sm" data-action="test-leetify" ${leetifyTestBusy||!cloudConfigured?'disabled':''}>${leetifyTestBusy?'TESTANDO...':'TESTAR LEETIFY'}</button></div><div class="admin-list">${db.players.slice().sort((a,b)=>a.nick.localeCompare(b.nick)).map(p=>`<div class="admin-list-item"><span><strong>${esc(p.nick)}</strong><small>SteamID64: ${esc(p.steamId64||'não cadastrado')}</small></span></div>`).join('')}</div>`;}
function renderAdminPlayers(){const p=byId(ui.editingId),newP=!p;const all=db.players.slice().sort((a,b)=>a.rank-b.rank);return `<div class="admin-players"><aside><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><b style="font-size:12px">ATLETAS (${db.players.length})</b><button class="btn btn-primary btn-sm" data-action="add-player">${ico('plus')} NOVO</button></div><div class="admin-list">${all.map(player=>`<button class="admin-list-item ${p?.id===player.id?'active':''}" data-admin-edit="${esc(player.id)}">${portrait(player)}<span><strong>${esc(player.nick)}</strong><small>Ordem ${player.rank} · ${esc(player.role)}</small></span></button>`).join('')}</div></aside><div><form id="playerForm"><div class="form-grid"><div class="form-section-name">${newP?'CADASTRAR JOGADOR':'EDITAR '+esc(p.nick)}</div><div class="field"><label for="fNick">Nick *</label><input id="fNick" name="nick" required maxlength="30" value="${esc(p?.nick||'')}" placeholder="Ex: KRYPT"></div><div class="field"><label for="fName">Nome completo</label><input id="fName" name="name" maxlength="65" value="${esc(p?.name||'')}" placeholder="Nome do jogador"></div><div class="field"><label for="fFlag">País / Bandeira</label><input id="fFlag" name="flag" maxlength="12" value="${esc(p?.flag||'ðŸ‡§ðŸ‡·')}"></div><div class="field"><label for="fRole">Função in-game</label><select name="role" id="fRole">${ROLES.map(r=>`<option value="${esc(r)}" ${r===(p?.role||ROLES[0])?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div class="field"><label for="fRank">Ordem interna</label><input id="fRank" type="number" name="rank" min="1" max="9999" value="${p?.rank||db.players.length+1}" required></div><div class="field"><label for="fTier">Tier definido pela organização</label><input id="fTier" name="tier" maxlength="20" value="${esc(p?.tier||'')}" placeholder="Ex.: Tier 2"></div><div class="field span2"><label for="fSteamId">SteamID64</label><input id="fSteamId" name="steamId64" inputmode="numeric" pattern="[0-9]{17}" maxlength="17" value="${esc(p?.steamId64||'')}" placeholder="17 dígitos"></div><div class="field span2"><label for="fPhoto">URL de foto (opcional)</label><input id="fPhoto" name="photoUrl" type="url" value="${p?.image?.startsWith('http')?esc(p.image):''}" placeholder="https://.../foto.png"></div><div class="field full"><label for="photoUpload">Ou enviar foto do computador (JPG / PNG)</label><input id="photoUpload" type="file" accept="image/png,image/jpeg,image/webp"><p id="uploadState" class="field-help">${ui.pendingPhoto?'✓ Imagem preparada':p?.image?'Foto cadastrada; o envio substitui a imagem atual.':'Sem foto? O site gera automaticamente um avatar ilustrado.'}</p></div><div class="field full"><label for="fBio">Observações / scouting</label><textarea id="fBio" name="bio" rows="2" maxlength="700">${esc(p?.bio||'')}</textarea></div><div class="field full"><p class="field-help">Estatísticas gerais são gerenciadas separadamente do registro oficial das partidas. O Tier não é alterado pela sincronização externa.</p></div></div><div class="form-actions">${p?`<button type="button" class="btn btn-warn" data-action="delete-player" data-id="${esc(p.id)}">${ico('trash')} EXCLUIR</button>`:''}<button type="submit" class="btn btn-primary">${ico('check')} ${newP?'CADASTRAR JOGADOR':'SALVAR ALTERAÇÕES'}</button></div></form>${p?renderIndividualScouting(p):'<p class="field-help">Salve o cadastro para adicionar análises de scouting.</p>'}</div></div>`;}
