 try{if(file.size>5*1024*1024)throw Error('Arquivo excede 5 MB.');const raw=JSON.parse(await file.text());if(ui.editingId!==id)throw Error('O jogador selecionado mudou. Selecione o arquivo novamente.');await stageIndividualScouting(raw);}
 catch(e){toast(e instanceof SyntaxError?'JSON inválido.':e.message||'Não foi possível ler o arquivo.',true);}
