  await commitScoutingSnapshot(fresh.version,localSnapshot,snapshot=>{const p=snapshot.players.find(x=>x.id===id);if(!p||JSON.stringify(p.scoutingAnalyses?.[index])!==JSON.stringify(current))throw Error('A análise mudou.');p.scoutingAnalyses=p.scoutingAnalyses.filter((_,i)=>i!==index);return snapshot;});
